test:
cache = PrefixCache()
cache.store((4,), 'old')
cache.store([4], 'new')
assert cache.lookup([4, 5]) == (1, 'new')
assert cache.remove([4]) is True
assert cache.remove([4]) is False
for invalid in ('12', [1, True], [-1]):
    try:
        cache.lookup(invalid)
        assert False
    except TypeError:
        pass
for tokens, value in (([], 'x'), ([1], '')):
    try:
        cache.store(tokens, value)
        assert False
    except ValueError:
        pass
